import { test, expect } from '@playwright/test';

test.describe('Billing Address Change During Checkout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully update billing address during checkout', async ({ page }) => {
    // Verify initial billing address is displayed
    const billingAddressInput = page.getByLabel('Billing Address');
    await expect(billingAddressInput).toBeVisible();

    // Verify initial billing address is correct
    const initialAddress = page.getByText('123 Main St, Anytown, USA');
    await expect(initialAddress).toBeVisible();

    // Verify initial billing address form is valid
    const billingAddressForm = page.locator('[data-testid="billing-address-form"]');
    await expect(billingAddressForm).toBeVisible();

    // Verify checkout button is disabled initially
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeDisabled();

    // Navigate to billing address update page
    const updateAddressButton = page.getByRole('button', { name: /update billing address/i });
    await expect(updateAddressButton).toBeVisible();
    await updateAddressButton.click();

    // Verify billing address form is now visible
    await expect(billingAddressForm).toBeVisible();

    // Update billing address
    const newAddressInput = page.getByLabel('Billing Address');
    await newAddressInput.fill('456 Elm St, Othertown, USA');

    // Verify new address is displayed
    const newAddress = page.getByText('456 Elm St, Othertown, USA');
    await expect(newAddress).toBeVisible();

    // Verify address validation error is cleared
    const addressValidationError = page.getByText(/is required/i);
    await expect(addressValidationError).not.toBeVisible();

    // Verify checkout button is now enabled
    await expect(checkoutButton).toBeEnabled();

    // Verify success message is displayed
    const successMessage = page.getByText(/billing address updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify checkout button is clickable
    await expect(checkoutButton).toBeClickable();

    // Click checkout button to complete the process
    await checkoutButton.click();

    // Verify order confirmation page is displayed
    const orderConfirmation = page.getByText(/order confirmation/i);
    await expect(orderConfirmation).toBeVisible();
  });

  test('should display error when billing address is invalid during checkout', async ({ page }) => {
    // Navigate to checkout
    await page.goto('/checkout');

    // Verify initial billing address is displayed
    const billingAddressInput = page.getByLabel('Billing Address');
    await expect(billingAddressInput).toBeVisible();

    // Verify initial billing address is correct
    const initialAddress = page.getByText('123 Main St, Anytown, USA');
    await expect(initialAddress).toBeVisible();

    // Verify initial billing address form is valid
    const billingAddressForm = page.locator('[data-testid="billing-address-form"]');
    await expect(billingAddressForm).toBeVisible();

    // Verify checkout button is disabled initially
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).toBeDisabled();

    // Navigate to billing address update page
    const updateAddressButton = page.getByRole('button', { name: /update billing address/i });
    await updateAddressButton.click();

    // Verify billing address form is now visible
    await expect(billingAddressForm).toBeVisible();

    // Attempt to update billing address with invalid data
    const newAddressInput = page.getByLabel('Billing Address');
    await newAddressInput.fill('');

    // Verify validation error is displayed
    const addressValidationError = page.getByText(/is required/i);
    await expect(addressValidationError).toBeVisible();

    // Verify checkout button is still disabled
    await expect(checkoutButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/please enter a valid address/i);
    await expect(errorMessage).toBeVisible();

    // Verify billing address input is still visible
    await expect(newAddressInput).toBeVisible();
  });
});
